insert into public.vocabulary_items
(vocabulary_id,term,part_of_speech,core_meaning,senses,word_family,collocations,status)
values
('vocab_digital_native','digital native','noun','a person who has grown up using computers, the internet and mobile phones','[{"senseId":"digital_native_1","meaning":"a person who has grown up using computers, the internet and mobile phones","acceptedParaphrases":["someone raised with technology","a person who grew up online"],"masteryContexts":[{"contextId":"u9_11_digital_native_meaning","text":"Teachers sometimes assume that a digital native knows how to search online safely, but this is not always true.","meaning":"young people who have grown up with digital technology","wrongMeanings":["someone who works in a computer shop","someone who avoids using the internet","someone who moved from another country"]},{"contextId":"u9_11_digital_native_paraphrase","text":"My parents learned to use computers at work, but my sister is a true digital native.","meaning":"a person who has used technology since childhood","wrongMeanings":["a person who designs computer programs","a person who learned technology late in life","a person who works from home"]}],"situationDistractors":["A man used his first computer when he was forty and still finds it difficult.","A woman moved to a new country and learned to speak the local language.","An engineer spends every day designing parts for laptops.","A woman learned to use email when she started work at fifty.","A man prefers paper maps because he never learned to use a phone map.","A grandmother bought her first smartphone last year."],"gapDistractors":[{"contextId":"u9_11_digital_native_gap_1","answer":"digital native","wrong":["conclusion","reporting verb","clause"]},{"contextId":"u9_11_digital_native_gap_2","answer":"digital native","wrong":["conference","clause","conclusion"]},{"contextId":"u9_11_digital_native_gap_3","answer":"digital native","wrong":["conclusion","clause","direct object"]}],"spellingErrors":["digitle native","digital nativ","digital natve","diggital native","digital nateve","digetal native"],"masteryPassages":[{"passageId":"u9_11_digital_native_passage_1","contextId":"u9_11_digital_native_gap_1","text":"Sara was born in 2010 and has used a tablet since she was two. As a ____, she cannot imagine life without the internet.","answer":"digital native"},{"passageId":"u9_11_digital_native_passage_2","contextId":"u9_11_digital_native_gap_2","text":"My father learned to use computers at work when he was thirty. My little brother, who is a ____, learned before he could read.","answer":"digital native"}],"contextDependentParaphrases":[],"wrongParaphrases":["someone who repairs computers","someone who avoids the internet","someone born abroad"],"misleadingDistractors":["a person who builds computers for a living","someone who refuses to use the internet","a person who was born in a different country"],"teacherNote":"Noun phrase (countable): a person who has grown up surrounded by digital technology (digital natives, a generation of digital natives). Contrast with older people who learned technology as adults. It is a fixed phrase, so Word Families is not counted for it."}]'::jsonb,'[]'::jsonb,'["a true digital native","a generation of digital natives","digital natives and older users"]'::jsonb,'live'),
('vocab_accuracy','accuracy','noun','the quality of being correct and exact, without mistakes','[{"senseId":"accuracy_1","meaning":"the quality of being correct and exact, without mistakes","acceptedParaphrases":["correctness","being exact"],"masteryContexts":[{"contextId":"u9_12_accuracy_meaning","text":"Translation apps have improved, but their accuracy is still a problem with informal language.","meaning":"how correct and exact something is","wrongMeanings":["how quickly something is done","how cheap something is","how popular something is"]},{"contextId":"u9_12_accuracy_paraphrase","text":"In the writing paper, marks are given for both content and language accuracy.","meaning":"correctness without mistakes","wrongMeanings":["speed without hesitation","creativity and imagination","length and detail"]}],"situationDistractors":["A boy finished his test very quickly without checking any answers.","A girl felt nervous before her speech, even though she was well prepared.","A family compared the prices of three phones before choosing one.","A runner finished the race in record time.","A girl felt proud after she gave her first speech.","A boy bought the cheapest calculator in the shop."],"gapDistractors":[{"contextId":"u9_12_accuracy_gap_1","answer":"accuracy","wrong":["workforce","frustration","audience"]},{"contextId":"u9_12_accuracy_gap_2","answer":"accuracy","wrong":["frustration","generation","community"]},{"contextId":"u9_12_accuracy_gap_3","answer":"accuracy","wrong":["workforce","community","conference"]}],"spellingErrors":["accurasy","acuracy","accurecy","accuricy","acurracy","accuarcy"],"wordFamilyForms":[{"form":"accuracy","partOfSpeech":"noun","example":"Journalists must check the accuracy of every fact.","pedagogicallyUseful":true},{"form":"accurate","partOfSpeech":"adjective","example":"The weather forecast was surprisingly accurate this week.","pedagogicallyUseful":true,"altExample":"Make sure your notes are accurate before you share them."},{"form":"inaccurate","partOfSpeech":"adjective","example":"Many online maps were inaccurate after the new road opened.","pedagogicallyUseful":true,"altExample":"The article was removed because it contained inaccurate figures."}],"masteryPassages":[{"passageId":"u9_12_accuracy_passage_1","contextId":"u9_12_accuracy_gap_1","text":"Before publishing the article, the editor checked every date and name. She was worried about the ____ of the information.","answer":"accuracy"},{"passageId":"u9_12_accuracy_passage_2","contextId":"u9_12_accuracy_gap_2","text":"Spelling and grammar mistakes lose marks in the writing paper. The examiners look for ____ as well as interesting ideas.","answer":"accuracy"}],"contextDependentParaphrases":[],"wrongParaphrases":["speed","confidence","price"],"misleadingDistractors":["the speed at which something is done","the amount of money something costs","the feeling of being confident"],"teacherNote":"Noun (uncountable): the quality of being correct and exact (accuracy of information, with great accuracy, check the accuracy). Boundary: accuracy is about being correct; fluency is about speaking smoothly; the two are often contrasted in language learning. The adjective accurate, the adverb accurately and the opposites inaccurate/inaccuracy are taught in the Word Family pathway."}]'::jsonb,'["accurate","inaccurate"]'::jsonb,'["check the accuracy of","with great accuracy","accuracy and fluency"]'::jsonb,'live'),
('vocab_appropriate','appropriate','adjective','suitable or right for a particular situation, person or purpose','[{"senseId":"appropriate_1","meaning":"suitable or right for a particular situation, person or purpose","acceptedParaphrases":["suitable","right for the situation"],"masteryContexts":[{"contextId":"u9_13_appropriate_meaning","text":"Slang is fine in a text to a friend, but it is not appropriate in an email to your teacher.","meaning":"suitable for the situation","wrongMeanings":["too long for the situation","difficult for the situation","funny in the situation"]},{"contextId":"u9_13_appropriate_paraphrase","text":"The film is not appropriate for young children because it contains violence.","meaning":"right or acceptable for a particular person","wrongMeanings":["interesting to a particular person","too expensive for a particular person","frightening for a particular person"]}],"situationDistractors":["A girl wore a beautiful new dress that cost a lot of money.","A student used a very old textbook that the school no longer uses.","A boy told a joke that nobody in the class understood.","A girl chose the most expensive dress in the shop.","A boy used a very long word that he did not understand.","A student arrived ten minutes early for the lesson."],"gapDistractors":[{"contextId":"u9_13_appropriate_gap_1","answer":"appropriate","wrong":["tech-savvy","portable","banned"]},{"contextId":"u9_13_appropriate_gap_2","answer":"appropriate","wrong":["tech-savvy","interactive","underlying"]},{"contextId":"u9_13_appropriate_gap_3","answer":"appropriate","wrong":["portable","tech-savvy","virtual"]}],"spellingErrors":["apropriate","appropiate","appropriete","approprate","apropriat","appropreate"],"wordFamilyForms":[{"form":"appropriate","partOfSpeech":"adjective","example":"Jeans are not appropriate for a formal interview.","pedagogicallyUseful":true},{"form":"appropriately","partOfSpeech":"adverb","example":"Students should dress appropriately for the school concert.","pedagogicallyUseful":true,"altExample":"He apologised and behaved appropriately for the rest of the day."},{"form":"inappropriate","partOfSpeech":"adjective","example":"Posting a classmate’s photo without permission is inappropriate.","pedagogicallyUseful":true,"altExample":"The teacher removed an inappropriate comment from the class forum."}],"masteryPassages":[{"passageId":"u9_13_appropriate_passage_1","contextId":"u9_13_appropriate_gap_1","text":"Shorts and flip-flops are fine for the beach. They are not ____ for a job interview at a bank.","answer":"appropriate"},{"passageId":"u9_13_appropriate_passage_2","contextId":"u9_13_appropriate_gap_2","text":"When you write to your head teacher, avoid slang and emojis. Choose language that is polite and ____.","answer":"appropriate"}],"contextDependentParaphrases":[],"wrongParaphrases":["expensive","unusual","difficult"],"misleadingDistractors":["very expensive and fashionable","strange and difficult to understand","old and no longer used"],"teacherNote":"Adjective: suitable or right for a particular situation (appropriate for/to, appropriate language, appropriate behaviour). Very common in exam rubrics about register. Boundary: appropriate and suitable are close synonyms; Precision items show where each sounds natural. The opposite inappropriate and the adverb appropriately are taught in the Word Family pathway. Note: the verb \"appropriate\" (take for yourself) is a different word and is not taught."}]'::jsonb,'["appropriately","inappropriate"]'::jsonb,'["appropriate for","appropriate language","not appropriate in"]'::jsonb,'live'),
('vocab_banned','banned','adjective','officially not allowed by a rule or law','[{"senseId":"banned_1","meaning":"officially not allowed by a rule or law","acceptedParaphrases":["not allowed","officially forbidden"],"masteryContexts":[{"contextId":"u9_14_banned_meaning","text":"In some schools, smartphones are banned from the classroom to help students concentrate.","meaning":"officially not allowed","wrongMeanings":["strongly recommended","made cheaper","officially required"]},{"contextId":"u9_14_banned_paraphrase","text":"The player was banned from the next three matches for arguing with the referee.","meaning":"officially stopped from doing something","wrongMeanings":["officially chosen to do something","paid extra to do something","trained to do something"]}],"situationDistractors":["The teacher strongly recommended that everyone read the novel.","A new game became so popular that all the shops sold out.","The library let students borrow laptops for the weekend.","The school encouraged all students to join a club.","The shop gave free samples to every customer.","The library allowed visitors to stay until midnight."],"gapDistractors":[{"contextId":"u9_14_banned_gap_1","answer":"banned","wrong":["launched","evaluated","represented"]},{"contextId":"u9_14_banned_gap_2","answer":"banned","wrong":["interactive","portable","tech-savvy"]},{"contextId":"u9_14_banned_gap_3","answer":"banned","wrong":["launched","evaluated","suggested"]}],"spellingErrors":["baned","bannned","bannd","bandd","banedd","bannet"],"masteryPassages":[{"passageId":"u9_14_banned_passage_1","contextId":"u9_14_banned_gap_1","text":"Several students were caught using their phones during the exam. Since then, phones have been ____ from the exam hall completely.","answer":"banned"},{"passageId":"u9_14_banned_passage_2","contextId":"u9_14_banned_gap_2","text":"The government decided the chemical was too dangerous. It is now ____ in all toys sold in the country.","answer":"banned"}],"contextDependentParaphrases":[],"wrongParaphrases":["encouraged","required","advertised"],"misleadingDistractors":["strongly recommended by teachers","available only to adults","newly invented and popular"],"teacherNote":"Adjective / past participle: officially not allowed (banned from ..., banned in ..., a banned substance). Usually used after be (are banned) or before a noun (a banned app). Boundary: banned is an official rule; discouraged only means advised against. The base verb ban and the noun ban are taught in the Word Family pathway."}]'::jsonb,'[]'::jsonb,'["banned from","banned in","officially banned"]'::jsonb,'live'),
('vocab_community','community','noun','a group of people who live in the same area or share the same interests','[{"senseId":"community_1","meaning":"a group of people who live in the same area or share the same interests","acceptedParaphrases":["local group of people","people with shared interests"],"masteryContexts":[{"contextId":"u9_15_community_meaning","text":"Social media allows people with rare hobbies to find a community of others who share their interest.","meaning":"a group of people with the same interests","wrongMeanings":["a company that sells products","a website that stores files","a person who works alone"]},{"contextId":"u9_15_community_paraphrase","text":"After the earthquake, the whole community worked together to rebuild homes.","meaning":"the people who live in one area","wrongMeanings":["the government of the country","the workers from abroad","the tourists visiting the area"]}],"situationDistractors":["An old woman lives alone on a farm far from any village.","A large company opened a new factory and hired engineers.","A boy spent the weekend playing a computer game by himself.","A man spent the whole weekend alone in his flat.","A company moved its offices to another country.","A girl studied by herself in her bedroom."],"gapDistractors":[{"contextId":"u9_15_community_gap_1","answer":"community","wrong":["accuracy","perception","frustration"]},{"contextId":"u9_15_community_gap_2","answer":"community","wrong":["accuracy","frustration","conclusion"]},{"contextId":"u9_15_community_gap_3","answer":"community","wrong":["accuracy","perception","frustration"]}],"spellingErrors":["comunity","communitey","communety","commnity","comminity","communty"],"masteryPassages":[{"passageId":"u9_15_community_passage_1","contextId":"u9_15_community_gap_1","text":"When the old library was going to close, local people raised money to save it. The whole ____ came together to help.","answer":"community"},{"passageId":"u9_15_community_passage_2","contextId":"u9_15_community_gap_2","text":"Kai loves building model trains. He has joined an online ____ of people from all over the world who share the same hobby.","answer":"community"}],"contextDependentParaphrases":[],"wrongParaphrases":["company","building","individual"],"misleadingDistractors":["a large company that makes and sells products","a single person who lives alone","a building where meetings are held"],"teacherNote":"Noun (countable, also used collectively): a group of people living in one area or sharing interests (the local community, an online community, community centre). Boundary: a community is people; a building where it meets is a community centre. The adjective communal is related but not taught; Word Families is not counted for community."}]'::jsonb,'[]'::jsonb,'["the local community","an online community","a community centre"]'::jsonb,'live'),
('vocab_optional','optional','adjective','available to choose, but not required or compulsory','[{"senseId":"optional_1","meaning":"available to choose, but not required or compulsory","acceptedParaphrases":["not compulsory","a matter of choice"],"masteryContexts":[{"contextId":"u9_16_optional_meaning","text":"In our school, music is optional after Year 9, so students can drop it if they prefer.","meaning":"not compulsory; you can choose","wrongMeanings":["compulsory for everyone","too difficult to continue","only for the best students"]},{"contextId":"u9_16_optional_paraphrase","text":"Wearing a tie is optional on Fridays, but most teachers still wear one.","meaning":"a choice, not a rule","wrongMeanings":["a strict rule for everyone","a punishment for breaking rules","a tradition from the past"]}],"situationDistractors":["Every driver must wear a seat belt, or they will be fined.","All students had to sit the final exam on the same morning.","The match was cancelled because of heavy rain.","Every visitor must show a passport at the border.","All workers have to wear a helmet on the building site.","Every student must take the maths exam."],"gapDistractors":[{"contextId":"u9_16_optional_gap_1","answer":"optional","wrong":["tech-savvy","portable","non-verbal"]},{"contextId":"u9_16_optional_gap_2","answer":"optional","wrong":["tech-savvy","non-verbal","face-to-face"]},{"contextId":"u9_16_optional_gap_3","answer":"optional","wrong":["tech-savvy","portable","non-verbal"]}],"spellingErrors":["opsional","optionel","optinal","opptional","optionnal","optionall"],"wordFamilyForms":[{"form":"optional","partOfSpeech":"adjective","example":"Music lessons are optional after Year 9.","pedagogicallyUseful":true},{"form":"option","partOfSpeech":"noun","example":"Students have the option of studying a third language.","pedagogicallyUseful":true,"altExample":"Cycling to school is a healthy option for students who live nearby."},{"form":"opt","partOfSpeech":"verb","example":"Many families opt for online lessons in winter.","pedagogicallyUseful":true,"altExample":"More students now opt to study online at weekends."}],"masteryPassages":[{"passageId":"u9_16_optional_passage_1","contextId":"u9_16_optional_gap_1","text":"All students must take English and maths. Art and music, however, are ____ after Year 9.","answer":"optional"},{"passageId":"u9_16_optional_passage_2","contextId":"u9_16_optional_gap_2","text":"The basic app is free. Extra features cost money, but buying them is completely ____.","answer":"optional"}],"contextDependentParaphrases":[],"wrongParaphrases":["compulsory","cancelled","difficult"],"misleadingDistractors":["required by law for everyone","cancelled because of bad weather","extremely difficult to complete"],"teacherNote":"Adjective: available to choose but not required (an optional subject, optional extras, it is optional to ...). Opposite: compulsory / required. The noun option and the adverb optionally are taught in the Word Family pathway."}]'::jsonb,'["option","opt"]'::jsonb,'["an optional subject","completely optional","optional extras"]'::jsonb,'live'),
('vocab_survive','survive','verb','to continue to exist or be used, especially when there is a danger that something will disappear','[{"senseId":"survive_1","meaning":"to continue to exist or be used, especially when there is a danger that something will disappear","acceptedParaphrases":["continue to exist","last"],"masteryContexts":[{"contextId":"u9_17_survive_meaning","text":"Many small languages may not survive if young people stop speaking them.","meaning":"to continue to exist","wrongMeanings":["to become more popular","to change very quickly","to be replaced by something new"]},{"contextId":"u9_17_survive_paraphrase","text":"Experts were amazed that any of the ancient paintings could survive the fire in the museum.","meaning":"to remain after something dangerous has happened","wrongMeanings":["to be damaged badly by something","to be sold after something","to be copied after something"]}],"situationDistractors":["A new app became popular with millions of users in a single week.","An inventor created the first telephone in a small workshop.","A student copied a photo from a website without asking permission.","A new café opened in town and became popular at once.","A designer invented a completely new kind of chair.","A company copied a rival’s logo without permission."],"gapDistractors":[{"contextId":"u9_17_survive_gap_1","answer":"survive","wrong":["ban","recommend","evaluate"]},{"contextId":"u9_17_survive_gap_2","answer":"survive","wrong":["ban","evaluate","recommend"]},{"contextId":"u9_17_survive_gap_3","answer":"survive","wrong":["ban","recommend","evaluate"]}],"spellingErrors":["servive","survieve","survve","surrvive","survivee","surviv"],"wordFamilyForms":[{"form":"survive","partOfSpeech":"verb","example":"Only a few old letters survive from that century.","pedagogicallyUseful":true},{"form":"survival","partOfSpeech":"noun","example":"The survival of small languages depends on young speakers.","pedagogicallyUseful":true,"altExample":"Water is essential for survival in the desert."},{"form":"survivor","partOfSpeech":"noun","example":"The last survivor of the shipwreck told his story on the radio.","pedagogicallyUseful":true,"altExample":"Every survivor of the fire received help from the community."}],"masteryPassages":[{"passageId":"u9_17_survive_passage_1","contextId":"u9_17_survive_gap_1","text":"Many local languages are disappearing. Experts fear that only half of them will ____ until the end of the century.","answer":"survive"},{"passageId":"u9_17_survive_passage_2","contextId":"u9_17_survive_gap_2","text":"Most small bookshops closed when online shopping became popular. The few that managed to ____ now hold events to attract customers.","answer":"survive"}],"contextDependentParaphrases":[],"wrongParaphrases":["become popular","be invented","be copied"],"misleadingDistractors":["to become suddenly very popular","to be invented for the first time","to be copied without permission"],"teacherNote":"Verb: to continue to exist or live, especially despite danger or difficulty (survive the crisis, survive for years, will a tradition survive?). Unit 9 uses it for languages, traditions and old forms of communication. The noun survival and the noun survivor are taught in the Word Family pathway."}]'::jsonb,'["survival","survivor"]'::jsonb,'["survive for years","manage to survive","struggle to survive"]'::jsonb,'live'),
('vocab_unlike','unlike','preposition','different from someone or something, or in contrast to them','[{"senseId":"unlike_1","meaning":"different from someone or something, or in contrast to them","acceptedParaphrases":["in contrast to","different from"],"masteryContexts":[{"contextId":"u9_18_unlike_meaning","text":"An email, unlike a phone call, gives you time to think carefully about what you want to say.","meaning":"in contrast to","wrongMeanings":["in the same way as","because of","at the same time as"]},{"contextId":"u9_18_unlike_paraphrase","text":"Our new teacher, unlike the previous one, lets us use dictionaries in tests.","meaning":"different from","wrongMeanings":["similar to","chosen by","replaced by"]}],"situationDistractors":["Both twins love football and support the same team.","The two phones have exactly the same features and price.","Like her mother, Sara wants to become a doctor.","Both brothers prefer phoning people to sending messages.","The two essays made exactly the same points.","Like her friends, Lily uses video calls every day."],"gapDistractors":[{"contextId":"u9_18_unlike_gap_1","answer":"unlike","wrong":["optional","casual","banned"]},{"contextId":"u9_18_unlike_gap_2","answer":"unlike","wrong":["optional","banned","portable"]},{"contextId":"u9_18_unlike_gap_3","answer":"unlike","wrong":["optional","portable","banned"]}],"spellingErrors":["unlik","unlicke","unnlike","unlyke","unliek","onlike"],"masteryPassages":[{"passageId":"u9_18_unlike_passage_1","contextId":"u9_18_unlike_gap_1","text":"Leo loves talking on the phone for hours. His sister, ____ him, prefers to send short messages.","answer":"unlike"},{"passageId":"u9_18_unlike_passage_2","contextId":"u9_18_unlike_gap_2","text":"A letter takes days to arrive. An email, ____ a letter, reaches the reader in seconds.","answer":"unlike"}],"contextDependentParaphrases":[],"wrongParaphrases":["in the same way as","because of","as well as"],"misleadingDistractors":["in the same way as","because of","at the same time as"],"teacherNote":"Preposition: different from, or in contrast to (Unlike X, Y ...; X, unlike Y, ...). Very useful for comparing in writing. Boundary: unlike is a preposition, so it is followed by a noun or pronoun, not a clause (*unlike he does). It is a function word with no useful family here, so Word Families is not counted; the adjective unlikely is a different word."}]'::jsonb,'[]'::jsonb,'["unlike most people","unlike in the past","very unlike"]'::jsonb,'live'),
('vocab_frustration','frustration','noun','the feeling of being annoyed or upset because you cannot do or achieve what you want','[{"senseId":"frustration_1","meaning":"the feeling of being annoyed or upset because you cannot do or achieve what you want","acceptedParaphrases":["annoyance","feeling of being blocked"],"masteryContexts":[{"contextId":"u9_19_frustration_meaning","text":"After trying to explain the problem three times, the customer sighed with frustration.","meaning":"annoyance because something is not working","wrongMeanings":["great excitement because something worked","deep sadness because of a loss","calm patience while waiting"]},{"contextId":"u9_19_frustration_paraphrase","text":"Not being able to express yourself in a new language can cause great frustration.","meaning":"the feeling of being unable to do what you want","wrongMeanings":["the feeling of being extremely tired","the feeling of being proud","the feeling of being frightened"]}],"situationDistractors":["A girl smiled widely when she heard she had won the competition.","A boy felt sleepy after staying up late to finish a film.","A child hid under the bed during a loud thunderstorm.","A boy laughed happily as he opened his birthday presents.","A girl felt calm and relaxed on the beach.","A student was surprised by an unexpected visit from her cousin."],"gapDistractors":[{"contextId":"u9_19_frustration_gap_1","answer":"frustration","wrong":["accuracy","research","introduction"]},{"contextId":"u9_19_frustration_gap_2","answer":"frustration","wrong":["accuracy","introduction","research"]},{"contextId":"u9_19_frustration_gap_3","answer":"frustration","wrong":["accuracy","research","introduction"]}],"spellingErrors":["frustation","frustrasion","fustration","frustratoin","frusteration","frustraton"],"wordFamilyForms":[{"form":"frustration","partOfSpeech":"noun","example":"She shouted in frustration when her laptop crashed again.","pedagogicallyUseful":true},{"form":"frustrated","partOfSpeech":"adjective","example":"Users felt frustrated by the slow website.","pedagogicallyUseful":true,"altExample":"The frustrated customer called the helpline three times."},{"form":"frustrating","partOfSpeech":"adjective","example":"Waiting for a reply to an important message is frustrating.","pedagogicallyUseful":true,"altExample":"It is frustrating when an app keeps logging you out."}],"masteryPassages":[{"passageId":"u9_19_frustration_passage_1","contextId":"u9_19_frustration_gap_1","text":"Mia tried to join the online lesson five times, but the connection kept failing. In ____, she closed her laptop and phoned her teacher.","answer":"frustration"},{"passageId":"u9_19_frustration_passage_2","contextId":"u9_19_frustration_gap_2","text":"Not understanding what people say in a new country can cause great ____. Many students feel annoyed and helpless at first.","answer":"frustration"}],"contextDependentParaphrases":[],"wrongParaphrases":["excitement","fear","tiredness"],"misleadingDistractors":["a feeling of great happiness","the feeling of being frightened","a feeling of being very tired"],"teacherNote":"Noun: the feeling of being annoyed or upset because you cannot achieve something (in frustration, a source of frustration, frustration with/at). Boundary: frustration comes from being blocked or unable; anger is wider; disappointment comes from results being worse than expected. The verb frustrate and the adjectives frustrated/frustrating are taught in the Word Family pathway."}]'::jsonb,'["frustrated","frustrating"]'::jsonb,'["in frustration","a source of frustration","frustration with"]'::jsonb,'live'),
('vocab_informal','informal','adjective','relaxed and friendly, not following strict or official rules','[{"senseId":"informal_1","meaning":"relaxed and friendly, not following strict or official rules","acceptedParaphrases":["relaxed","not official"],"masteryContexts":[{"contextId":"u9_20_informal_meaning","text":"An email to a close friend can be informal, with short sentences and contractions.","meaning":"relaxed in style","wrongMeanings":["serious and polite in style","long and detailed in style","scientific in style"]},{"contextId":"u9_20_informal_paraphrase","text":"Before the official interview, there was an informal chat to help candidates relax.","meaning":"not official or following strict rules","wrongMeanings":["very strict and serious","secret and private","long and tiring"]}],"situationDistractors":["The president gave a serious speech at a state ceremony.","A lawyer wrote an official letter using legal language.","A scientist published a detailed report in a university journal.","A head teacher gave an official speech at graduation.","A government department sent out a formal letter.","A judge read out the decision in court."],"gapDistractors":[{"contextId":"u9_20_informal_gap_1","answer":"informal","wrong":["banned","portable","tech-savvy"]},{"contextId":"u9_20_informal_gap_2","answer":"informal","wrong":["portable","tech-savvy","banned"]},{"contextId":"u9_20_informal_gap_3","answer":"informal","wrong":["portable","banned","tech-savvy"]}],"spellingErrors":["informel","infomal","informall","inforaml","imformal","informul"],"wordFamilyForms":[{"form":"informal","partOfSpeech":"adjective","example":"Text messages are usually written in an informal style.","pedagogicallyUseful":true},{"form":"informally","partOfSpeech":"adverb","example":"The two managers chatted informally before the meeting.","pedagogicallyUseful":true,"altExample":"The students discussed the plan informally over lunch."},{"form":"formal","partOfSpeech":"adjective","example":"A job application should be written in a formal style.","pedagogicallyUseful":true,"altExample":"Please use formal language in your letter to the council."}],"masteryPassages":[{"passageId":"u9_20_informal_passage_1","contextId":"u9_20_informal_gap_1","text":"In a message to your best friend, you can use contractions and short sentences. This kind of ____ writing would be wrong in a report.","answer":"informal"},{"passageId":"u9_20_informal_passage_2","contextId":"u9_20_informal_gap_2","text":"There was no agenda and no official notes. It was just an ____ meeting over coffee to share ideas.","answer":"informal"}],"contextDependentParaphrases":[],"wrongParaphrases":["serious","official","scientific"],"misleadingDistractors":["very serious and polite","following strict official rules","written for a scientific journal"],"teacherNote":"Adjective: relaxed, friendly and not following strict rules (an informal meeting, informal clothes, informal email). Boundary: informal describes the situation or style; casual is especially used for clothes and attitudes. The opposite formal, the adverb informally and the noun informality are taught in the Word Family pathway. The fixed phrase \"informal language\" is taught as a separate target."}]'::jsonb,'["informally","formal"]'::jsonb,'["an informal meeting","an informal chat","informal clothes"]'::jsonb,'live')
insert into public.vocabulary_unit_occurrences
(occurrence_id,vocabulary_id,unit_number,unit_title,set_number,position_in_unit,sense_id,status,active)
values
('u9_11_digital_native','vocab_digital_native',9,'Communication',2,11,'digital_native_1','live',true),
